import duckdb, json, glob, datetime
from decimal import Decimal
orders={}
for p in sorted(glob.glob("/home/user/adss-2026-09-07/das/fixtures/orders/page-*.json")):
    for r in json.load(open(p, encoding="utf-8"), parse_float=Decimal)["value"]:
        orders[str(r["OrderId"])] = r
con = duckdb.connect("/home/user/adss-2026-09-07/warehouse.duckdb", read_only=True)
rows = con.execute("select order_key, customer_key, _event_date, _measure__order__freight_orders_amount, _measure__order__placed_orders_count from dar__uss._bridge where _event='placed'").fetchall()
con.close()
print("bridge rows:", len(rows), "| fixture orders:", len(orders))
missing = set(orders) - {r[0] for r in rows}
extra   = {r[0] for r in rows} - set(orders)
print("orders in fixtures but not on bridge:", len(missing), sorted(missing)[:10])
print("bridge order_keys not in fixtures  :", len(extra), sorted(extra)[:10])
bad_cust=bad_date=bad_freight=bad_count=0
examples=[]
for ok, ck, ed, fr, cnt in rows:
    src = orders[ok]
    if ck != src["CustomerId"]:
        bad_cust+=1; examples.append(("CUST", ok, ck, src["CustomerId"]))
    if str(ed) != src["OrderDate"]:
        bad_date+=1; examples.append(("DATE", ok, str(ed), src["OrderDate"]))
    if Decimal(fr) != Decimal(src["Freight"]):
        bad_freight+=1; examples.append(("FREIGHT", ok, fr, src["Freight"]))
    if cnt != 1:
        bad_count+=1; examples.append(("COUNT", ok, cnt))
print("per-order mismatches -> customer:", bad_cust, "date:", bad_date, "freight:", bad_freight, "count!=1:", bad_count)
for e in examples[:10]: print("   ", e)
PYEOF
